"IA-2(10)": {"statement":[{"prose":"Provide a single sign-on capability for [Assignment: organization-defined system accounts and services]."}],"discussion":["Single sign-on enables users to log in once and gain access to multiple system resources. Organizations consider the operational efficiencies provided by single sign-on capabilities with the risk introduced by allowing access to multiple systems via a single authentication event. Single sign-on can present opportunities to improve system security, for example by providing the ability to add multi-factor authentication for applications and systems (existing and new) that may not be able to natively support multi-factor authentication."],"params":[{"id":"IA-02(10)_ODP","kind":"Assignment","value":"[Assignment: organization-defined system accounts and services]","guideline":"system accounts and services for which a single sign-on capability must be provided are defined"}],"related":[],"objectives":[{"id":"ia-2.10_obj","label":"IA-02(10)","prose":"a single sign-on capability is provided for [Assignment: organization-defined system accounts and services]."}],"methods":[{"method":"Examine","objects":["Identification and authentication policy","system security plan","procedures addressing single sign-on capability for system accounts and services","procedures addressing identification and authentication","system design documentation","system configuration settings and associated documentation","system audit records","list of system accounts and services requiring single sign-on capability","other relevant documents or records"]},{"method":"Interview","objects":["Organizational personnel with system operations responsibilities","organizational personnel with account management responsibilities","organizational personnel with information security responsibilities","system/network administrators","system developers"]},{"method":"Test","objects":["Mechanisms supporting and/or implementing identification and authentication capabilities","mechanisms supporting and/or implementing single sign-on capability for system accounts and services"]}],"references":[]},
